page_settings.custom_css:
@import url('https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,300;1,9..144,300&family=Manrope:wght@200;300;400;500;600;700;800&family=Inter:wght@300;400;500;600&family=JetBrains+Mono:wght@400;500&display=swap');

html{scroll-behavior:smooth;}
body,.elementor-page{background:#f4f0ea!important;}
*{box-sizing:border-box;}
em,.d1-em{font-style:italic;color:#1f5e57;}

/* ── Eyebrow ─── */
.d1-eyebrow .elementor-heading-title{
  font-family:'Manrope',sans-serif!important;font-weight:500!important;
  font-size:11px!important;letter-spacing:0.22em!important;
  text-transform:uppercase!important;color:#1f5e57!important;}

/* ══ FLOATING PILL NAV (overlays hero) ═══════════════════════ */
.d1-pillnav-section{
  position:relative;z-index:30;
  margin-bottom:-890px!important;}
.d1-pillnav-section>.elementor-container{
  display:flex;justify-content:space-between;align-items:center;
  padding:28px 28px 0!important;max-width:100%!important;}
.d1-pillnav-section .d1-brand-pill .elementor-button{
  background:rgba(244,240,234,.82)!important;
  backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);
  border:1px solid rgba(244,240,234,.65)!important;
  border-radius:999px!important;color:#1a1916!important;
  padding:13px 26px 13px 18px!important;font-size:13px!important;
  font-weight:700!important;letter-spacing:0.14em!important;
  display:inline-flex!important;align-items:center!important;gap:10px!important;
  transition:background .25s,color .25s!important;}
.d1-pillnav-section .d1-brand-pill .elementor-button::before{
  content:'';width:8px;height:8px;border-radius:50%;
  background:#1f5e57;display:inline-block;flex-shrink:0;}
.d1-pillnav-section .d1-brand-pill .elementor-button:hover{
  background:#1a1916!important;color:#ebe3d2!important;}
.d1-pillnav-section .elementor-nav-menu--main .elementor-item{
  padding:12px 22px!important;border-radius:999px!important;
  background:rgba(244,240,234,.72)!important;
  backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);
  border:1px solid rgba(244,240,234,.6)!important;
  margin:0 3px!important;color:#1a1916!important;
  font-size:13px!important;letter-spacing:0.02em!important;
  transition:background .25s,color .25s!important;}
.d1-pillnav-section .elementor-nav-menu--main .elementor-item:hover{
  background:#1a1916!important;color:#ebe3d2!important;}
.d1-pillnav-section .d1-contact-pill .elementor-button{
  background:rgba(244,240,234,.72)!important;
  backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);
  border:1px solid rgba(244,240,234,.6)!important;
  border-radius:999px!important;color:#1a1916!important;
  padding:13px 26px!important;font-size:13px!important;
  letter-spacing:0.04em!important;transition:background .2s,color .2s!important;}
.d1-pillnav-section .d1-contact-pill .elementor-button:hover{
  background:#1f5e57!important;color:#f4f0ea!important;}

/* ══ HERO ═════════════════════════════════════════════════════ */
.d1-hero-section{overflow:visible;padding:24px!important;}
.d1-hero-section>.elementor-container{padding:0!important;max-width:100%!important;}
.d1-hero-section .elementor-widget-slides,
.d1-hero-section .elementor-slides-wrapper{
  border-radius:28px;overflow:hidden;
  box-shadow:0 1px 0 rgba(26,25,22,.06);}
.d1-hero-section .swiper,.d1-hero-section .swiper-container,
.d1-hero-section .elementor-slides-wrapper,
.d1-hero-section .elementor-main-swiper{height:832px!important;}
.d1-hero-section .swiper-slide{align-items:flex-end!important;}
.d1-hero-section .elementor-slide-inner{
  width:100%!important;padding:0 64px 56px 64px!important;
  align-items:flex-start!important;text-align:left!important;flex-direction:column;}
.d1-hero-section .elementor-slide-content{text-align:left!important;max-width:1180px;}
.d1-hero-section .elementor-slide-heading .d1-ey{
  display:block;font-family:'Manrope',sans-serif!important;
  font-weight:500!important;font-size:11px!important;
  letter-spacing:0.22em!important;text-transform:uppercase;
  color:rgba(244,240,234,.8);margin-bottom:32px;line-height:1.4;}
.d1-hero-section .elementor-slide-heading .d1-ey::before{
  content:'';display:inline-block;width:32px;height:1px;
  background:#5a9d92;vertical-align:middle;margin-right:14px;}
.d1-hero-section .elementor-slide-heading{
  font-family:'Fraunces',serif!important;font-weight:300!important;
  font-size:96px!important;line-height:0.95!important;
  letter-spacing:-0.025em!important;color:#f4f0ea!important;
  margin:0 0 28px!important;white-space:pre-line;}
.d1-hero-section .elementor-slide-heading em{
  font-style:italic;color:rgba(244,240,234,.95);}
.d1-hero-section .elementor-slide-description{
  font-family:'Inter',sans-serif!important;font-size:15px!important;
  line-height:1.6!important;color:rgba(244,240,234,.9)!important;
  max-width:340px;margin:0 0 36px!important;}
.d1-hero-section .elementor-slide-description::before{
  content:'';display:block;width:24px;height:1px;
  background:rgba(244,240,234,.7);margin-bottom:16px;}
.d1-hero-section .elementor-slide-button{
  background:#f4f0ea!important;border:0!important;color:#1a1916!important;
  font-family:'Manrope',sans-serif!important;font-weight:500!important;
  font-size:13px!important;letter-spacing:0.06em!important;
  border-radius:999px!important;padding:14px 28px!important;
  transition:background .25s,color .25s!important;}
.d1-hero-section .elementor-slide-button:hover{
  background:#1f5e57!important;color:#f4f0ea!important;}
.d1-hero-section .swiper-pagination{
  bottom:32px!important;right:64px!important;
  left:auto!important;width:auto!important;text-align:right;}
.d1-hero-section .swiper-pagination-bullet{
  width:8px;height:4px;border-radius:2px;
  background:rgba(244,240,234,.35);opacity:1;margin:0 4px!important;
  transition:width .3s,background .3s;}
.d1-hero-section .swiper-pagination-bullet-active{
  width:24px!important;background:rgba(244,240,234,.9)!important;}
.d1-hero-section .elementor-background-overlay{
  background:
    linear-gradient(135deg,rgba(15,13,10,.72) 0%,rgba(15,13,10,.42) 45%,rgba(15,13,10,.30) 70%,rgba(15,13,10,.65) 100%),
    linear-gradient(180deg,rgba(15,13,10,.35) 0%,rgba(15,13,10,0) 30%,rgba(15,13,10,0) 60%,rgba(15,13,10,.55) 100%)
    !important;opacity:1!important;}

/* ── Hero bottom overlay ─── */
.d1-hero-overlay-section{
  position:relative;z-index:20;
  margin-top:-172px!important;
  background:transparent!important;
  pointer-events:none;}
.d1-hero-overlay-section>.elementor-container{
  padding:0 64px 56px!important;max-width:100%!important;
  align-items:center!important;}
.d1-hero-overlay-section>.elementor-container>.elementor-row{
  align-items:center;gap:24px;}
.d1-hero-overlay-section .elementor-column,
.d1-hero-overlay-section .elementor-element-populated{pointer-events:auto;}
/* info cards */
.d1-hero-card-inner{
  display:grid;grid-template-columns:90px 1fr;gap:22px;align-items:center;
  background:rgba(26,25,22,.55);backdrop-filter:blur(20px);
  -webkit-backdrop-filter:blur(20px);
  border:1px solid rgba(244,240,234,.18);
  border-radius:22px;padding:28px 32px;height:100%;
  transition:background .3s;}
.d1-hero-card-inner:hover{background:rgba(26,25,22,.68);}
.d1-hero-card-thumb{
  width:90px;height:90px;border-radius:16px;overflow:hidden;flex:0 0 auto;}
.d1-hero-card-thumb img{width:100%;height:100%;object-fit:cover;}
.d1-hero-card-body{display:flex;flex-direction:column;gap:6px;}
.d1-hero-card-tag{
  font-family:'JetBrains Mono',monospace;font-size:11px;
  letter-spacing:0.16em;text-transform:uppercase;color:#5a9d92;}
.d1-hero-card-body p{
  margin:0;font-size:14px;line-height:1.55;color:rgba(244,240,234,.94);}
/* CTA ring */
.d1-hero-cta-col>.elementor-element-populated{
  display:flex!important;justify-content:center!important;
  align-items:center!important;background:transparent!important;
  padding:0!important;}
.d1-cta-ring{
  width:168px;height:168px;border-radius:50%;
  background:#f4f0ea;color:#1a1916;
  display:grid;place-items:center;position:relative;cursor:pointer;
  box-shadow:0 12px 60px rgba(0,0,0,.35);
  transition:transform .4s cubic-bezier(.2,.7,.2,1),background .25s,color .25s;}
.d1-cta-ring:hover{transform:scale(1.04);background:#1f5e57;color:#f4f0ea;}
.d1-cta-ring-svg{
  position:absolute;inset:0;width:100%;height:100%;
  animation:d1-spin 22s linear infinite;}
.d1-cta-ring:hover .d1-cta-ring-svg{animation-duration:8s;}
.d1-cta-ring-svg text{
  font-family:'Manrope',sans-serif;font-weight:500;font-size:10.5px;
  letter-spacing:3px;text-transform:uppercase;fill:currentColor;}
.d1-cta-ring-inner{
  width:40px;height:40px;border-radius:50%;
  background:#1a1916;color:#f4f0ea;
  display:grid;place-items:center;
  transition:background .25s,color .25s;z-index:1;}
.d1-cta-ring:hover .d1-cta-ring-inner{background:#f4f0ea;color:#1f5e57;}
@keyframes d1-spin{to{transform:rotate(360deg);}}

/* ══ INTRO / BENTO ════════════════════════════════════════════ */
.d1-intro-section{background:#f4f0ea;}
.d1-stat-pill{
  background:#ebe6dd;border-radius:26px;padding:26px 28px;
  min-height:148px;display:flex;align-items:center;gap:22px;
  transition:background .25s;}
.d1-stat-pill:hover{background:#e2dccf;}
.d1-stat-pill .elementor-counter-number-wrapper{
  font-family:'Fraunces',serif!important;font-weight:300!important;
  font-size:52px!important;letter-spacing:-0.03em!important;color:#1a1916!important;}
.d1-stat-pill .elementor-counter-number-prefix{
  color:#1f5e57!important;font-style:italic!important;font-size:30px!important;
  line-height:1!important;}
.d1-stat-pill .elementor-counter-number-suffix{
  color:#1f5e57!important;font-style:italic!important;font-size:30px!important;
  line-height:1!important;}
.d1-stat-pill .elementor-counter-title{
  font-family:'Manrope',sans-serif!important;font-weight:500!important;
  font-size:11px!important;letter-spacing:0.18em!important;
  text-transform:uppercase!important;color:#6b665d!important;}
/* image thumb card */
.d1-thumb-card{
  border-radius:26px;overflow:hidden;background:#1a1916;
  min-height:148px;position:relative;cursor:pointer;}
.d1-thumb-card .elementor-widget-image img{
  width:100%;height:100%;object-fit:cover;position:absolute;inset:0;
  filter:brightness(0.7) saturate(0.85);
  transition:transform 1.2s cubic-bezier(.2,.7,.2,1),filter .6s;}
.d1-thumb-card:hover .elementor-widget-image img{
  transform:scale(1.06);filter:brightness(0.8) saturate(1);}
.d1-thumb-card>.elementor-element-populated{
  position:relative;z-index:2;display:flex!important;
  flex-direction:column!important;justify-content:space-between!important;
  padding:22px 24px!important;}
.d1-thumb-tag{
  font-family:'JetBrains Mono',monospace;font-size:11px;
  letter-spacing:0.14em;text-transform:uppercase;color:#5a9d92;}
.d1-thumb-title{
  font-family:'Manrope',sans-serif;font-weight:500;font-size:15px;
  letter-spacing:0.01em;line-height:1.35;color:#f4f0ea;}
/* editorial headline big */
.d1-intro-headline .elementor-heading-title{
  font-family:'Fraunces',serif!important;font-weight:300!important;
  font-size:92px!important;line-height:0.96!important;
  letter-spacing:-0.03em!important;color:#1a1916!important;}
.d1-intro-headline .elementor-heading-title em{font-style:italic;color:#1f5e57;}
/* aside tall image card */
.d1-aside-col{border-radius:26px;overflow:hidden;background:#1a1916;}
.d1-aside-col>.elementor-element-populated{
  display:flex;flex-direction:column;position:relative;}
.d1-aside-col .elementor-background-overlay{
  background:linear-gradient(to bottom,rgba(15,13,10,.1) 0%,rgba(15,13,10,.5) 65%,rgba(15,13,10,.85) 100%)!important;
  opacity:1!important;}
.d1-aside-col>.elementor-element-populated>.elementor-widget-wrap{
  display:flex;flex-direction:column;justify-content:space-between;
  height:100%;min-height:580px;padding:24px!important;}
.d1-aside-stat .elementor-counter-number-wrapper{
  font-family:'Fraunces',serif!important;font-weight:300!important;
  font-size:132px!important;letter-spacing:-0.04em!important;
  color:#f4f0ea!important;line-height:1!important;}
.d1-aside-stat .elementor-counter-title{
  font-family:'Manrope',sans-serif!important;font-weight:500!important;
  font-size:11px!important;letter-spacing:0.22em!important;
  text-transform:uppercase!important;color:rgba(244,240,234,.85)!important;
  margin-top:14px!important;text-align:center!important;}
.d1-aside-cta .elementor-heading-title{
  font-family:'Fraunces',serif!important;font-weight:300!important;
  font-style:italic;font-size:22px!important;color:#f4f0ea!important;}
.d1-aside-cta-sub-label{
  font-family:'Manrope',sans-serif!important;font-weight:400!important;
  font-size:11px!important;letter-spacing:0.16em!important;
  text-transform:uppercase;color:rgba(244,240,234,.72)!important;}

/* ══ SERVICES GRID ════════════════════════════════════════════ */
.d1-svc-row>.elementor-container{gap:22px!important;}
.d1-svc-row .elementor-row{gap:22px!important;}
.d1-svc-col{
  isolation:isolate;
  border-radius:22px!important;overflow:hidden;
  cursor:pointer;background:#26241f;}
/* Grayscale via backdrop-filter saturate on the overlay */
.d1-svc-col .elementor-background-overlay{
  background:rgba(40,36,30,.28)!important;
  backdrop-filter:saturate(0.12) brightness(0.58);
  -webkit-backdrop-filter:saturate(0.12) brightness(0.58);
  transition:
    backdrop-filter .9s cubic-bezier(.2,.7,.2,1),
    -webkit-backdrop-filter .9s cubic-bezier(.2,.7,.2,1),
    background .9s cubic-bezier(.2,.7,.2,1);
  opacity:1!important;}
.d1-svc-col:hover .elementor-background-overlay{
  background:linear-gradient(to bottom,rgba(15,13,10,.05) 0%,rgba(15,13,10,.30) 45%,rgba(15,13,10,.88) 100%)!important;
  backdrop-filter:saturate(1) brightness(1);
  -webkit-backdrop-filter:saturate(1) brightness(1);}
.d1-svc-col>.elementor-element-populated>.elementor-widget-wrap{
  display:flex!important;flex-direction:column!important;
  justify-content:space-between!important;
  min-height:480px;padding:28px 30px 30px!important;
  position:relative;z-index:1;}
.d1-svc-col .d1-svc-tag p{
  font-family:'JetBrains Mono',monospace!important;font-size:12px!important;
  letter-spacing:0.16em!important;text-transform:uppercase;
  color:#5a9d92!important;margin:0;
  display:inline-flex;align-items:center;gap:10px;}
.d1-svc-col .d1-svc-tag p::before{
  content:'';width:22px;height:1px;background:#5a9d92;display:inline-block;}
.d1-svc-col .d1-svc-title .elementor-heading-title{
  font-family:'Fraunces',serif!important;font-weight:300!important;
  font-size:44px!important;letter-spacing:-0.022em!important;
  line-height:1!important;color:#f4f0ea!important;margin:0!important;
  transition:font-style .35s;}
.d1-svc-col:hover .d1-svc-title .elementor-heading-title{font-style:italic;}
.d1-svc-col .d1-svc-desc .elementor-text-editor{
  max-height:0;overflow:hidden;opacity:0;
  transition:max-height .55s cubic-bezier(.2,.7,.2,1),opacity .4s ease;
  font-size:14px;line-height:1.6;color:rgba(244,240,234,.82);}
.d1-svc-col:hover .d1-svc-desc .elementor-text-editor{max-height:220px;opacity:1;}
.d1-svc-col .d1-svc-arrow{text-align:right;}
.d1-svc-col .d1-svc-arrow .elementor-button{
  width:46px!important;height:46px!important;padding:0!important;
  border-radius:50%!important;border:1px solid rgba(244,240,234,.28)!important;
  background:rgba(244,240,234,.12)!important;color:#f4f0ea!important;
  display:inline-flex!important;align-items:center!important;justify-content:center!important;
  font-size:16px!important;transition:all .3s!important;float:right;}
.d1-svc-col:hover .d1-svc-arrow .elementor-button{
  background:#1f5e57!important;border-color:#1f5e57!important;}

/* ══ SECTORS ══════════════════════════════════════════════════ */
.d1-sectors-section{background:#f4f0ea;}
.d1-sectors-section .elementor-column-gap-default .elementor-element-populated{
  padding:0!important;}
.d1-sectors-section .elementor-widget-text-editor .elementor-widget-container{
  padding:0!important;}
.d1-sector-row{
  display:flex;align-items:center;gap:32px;
  padding:36px 64px;border-bottom:1px solid rgba(26,25,22,.12);
  position:relative;cursor:pointer;transition:color .4s;color:#1a1916;
  overflow:hidden;}
.d1-sector-row::before{
  content:'';position:absolute;left:0;right:0;top:0;bottom:0;
  background:#1a1916;transform:scaleX(0);transform-origin:left;
  transition:transform .5s cubic-bezier(.2,.7,.2,1);z-index:0;}
.d1-sector-row:hover{color:#f4f0ea;}
.d1-sector-row:hover::before{transform:scaleX(1);}
.d1-sector-row>*{position:relative;z-index:1;}
.d1-sector-tag-cell{
  width:80px;font-family:'JetBrains Mono',monospace;
  font-size:12px;letter-spacing:0.14em;color:#8a857a;transition:color .4s;}
.d1-sector-row:hover .d1-sector-tag-cell{color:#5a9d92;}
.d1-sector-name-cell{
  flex:0 0 300px;font-family:'Fraunces',serif;font-weight:300;
  font-size:46px;line-height:1;letter-spacing:-0.022em;transition:font-style .45s;}
.d1-sector-row:hover .d1-sector-name-cell{font-style:italic;}
.d1-sector-desc-cell{
  flex:1;font-size:15px;line-height:1.6;color:#6b665d;transition:color .4s;}
.d1-sector-row:hover .d1-sector-desc-cell{color:rgba(244,240,234,.78);}
.d1-sector-cta-cell{
  display:flex;align-items:center;gap:14px;white-space:nowrap;}
.d1-sector-cta-text{
  font-family:'Manrope',sans-serif;font-weight:500;font-size:12px;
  letter-spacing:0.16em;text-transform:uppercase;color:#6b665d;transition:color .4s;}
.d1-sector-row:hover .d1-sector-cta-text{color:#f4f0ea;}
.d1-sector-arrow{
  width:48px;height:48px;border-radius:50%;
  border:1px solid rgba(26,25,22,.12);display:grid;place-items:center;
  transition:background .4s,color .4s,border-color .4s,transform .4s;}
.d1-sector-row:hover .d1-sector-arrow{
  background:#1f5e57;color:#f4f0ea;border-color:#1f5e57;transform:translate(2px,-2px);}

/* ══ METHODOLOGY ══════════════════════════════════════════════ */
.d1-method-section{position:relative;overflow:hidden;}
.d1-method-section::after{
  content:'';position:absolute;right:-120px;bottom:-120px;
  width:520px;height:520px;border-radius:50%;
  background:radial-gradient(circle,rgba(90,157,146,.15) 0%,transparent 70%);
  pointer-events:none;z-index:0;}
.d1-method-section>.elementor-container{position:relative;z-index:1;}
.d1-method-section .d1-eyebrow .elementor-heading-title{color:#5a9d92!important;}
.d1-method-section .d1-eyebrow .elementor-divider-separator{background:#5a9d92!important;}
.d1-pillar-col>.elementor-element-populated{
  border-top:1px solid rgba(235,227,210,.14)!important;
  padding:48px 32px 48px!important;}
.d1-pillar-col+.d1-pillar-col>.elementor-element-populated{
  border-left:1px solid rgba(235,227,210,.14)!important;}
.d1-pillar-col:first-child>.elementor-element-populated{padding-left:0!important;}
.d1-pillar-num p{
  font-family:'JetBrains Mono',monospace!important;font-size:12px!important;
  letter-spacing:0.15em!important;color:#5a9d92!important;margin:0;}

/* ══ CONTACT ══════════════════════════════════════════════════ */
.d1-contact-section{background:#f4f0ea;padding:100px 64px!important;}
.d1-contact-card{
  background:#ebe6dd;border-radius:32px;
  padding:80px 80px 60px!important;position:relative;overflow:hidden;}
.d1-contact-card::before{
  content:'Contact';
  position:absolute;left:50%;top:50%;transform:translate(-50%,-55%);
  font-family:'Fraunces',serif;font-weight:300;font-size:240px;
  font-style:italic;letter-spacing:-0.04em;color:#e2dccf;
  pointer-events:none;white-space:nowrap;user-select:none;z-index:0;}
.d1-contact-card>.elementor-element-populated{position:relative;z-index:1;}
.d1-contact-section .elementor-field-group label{
  font-family:'Manrope',sans-serif!important;font-weight:500!important;
  font-size:11px!important;letter-spacing:0.18em!important;
  text-transform:uppercase!important;color:#6b665d!important;}
.d1-contact-section .elementor-field{
  border:0!important;border-bottom:1px solid rgba(26,25,22,.15)!important;
  background:transparent!important;padding:10px 0!important;
  font-family:'Inter',sans-serif!important;font-size:17px!important;
  color:#1a1916!important;outline:none;border-radius:0!important;}
.d1-contact-section .elementor-field:focus{border-bottom-color:#1a1916!important;}
.d1-contact-section .elementor-button{
  border-radius:999px!important;padding:18px 32px!important;
  transition:background .25s!important;}
